/**
 * Web copy of shared/renewablePowerBalance.js. Keep the two files in sync.
 * Compare site power use with renewable generation.
 * electricity_renewable in emissionFactorRegistry.json is 0.1 kgCO2e/kWh.
 * Keep RENEWABLE_ELECTRICITY_KG_PER_KWH equal to that factor.
 * Transmission and distribution uses feraModeling.electricitySystemLossRate.
 */
import carbonDefaults from './carbonEmissionDefaults.json';

export const RENEWABLE_ELECTRICITY_KG_PER_KWH = 0.1;
export const ELECTRICITY_TD_LOSS_RATE = Number(carbonDefaults?.feraModeling?.electricitySystemLossRate) || 0.1763;

const toNonNegativeNumber = (value, fallback = 0) => {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) {
    return fallback;
  }
  return parsed;
};

const hasProvidedNumber = (data, key) => (
  data != null
  && Object.prototype.hasOwnProperty.call(data, key)
  && data[key] !== null
  && data[key] !== ''
);

const roundTo = (value, decimals = 2) => {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) {
    return 0;
  }
  return Number(numeric.toFixed(decimals));
};

/**
 * Self-use is renewable generation the site consumes.
 * When power use is greater, all generation is self-use and the rest is grid import.
 * When generation is greater, self-use stops at power use and the rest is grid export.
 * A declared onsite usage, when present, cannot exceed either figure.
 * When power use is omitted, self-use is not capped by consumption.
 */
export const allocateSiteRenewablePower = (data = {}) => {
  const generated = toNonNegativeNumber(data.solarGenerationKwhPerMonth, 0);
  const declaredUsage = toNonNegativeNumber(data.solarUsageKwhPerMonth, 0);
  const consumptionProvided = hasProvidedNumber(data, 'powerConsumptionKwhPerMonth');
  const consumed = consumptionProvided
    ? toNonNegativeNumber(data.powerConsumptionKwhPerMonth, 0)
    : null;

  let selfUsed = declaredUsage > 0 ? Math.min(declaredUsage, generated) : generated;
  if (consumed !== null) {
    selfUsed = Math.min(selfUsed, consumed);
  }

  const gridImport = consumed === null ? 0 : Math.max(0, consumed - selfUsed);
  const gridExport = Math.max(0, generated - selfUsed);
  let renewableBalance = 'none';
  if (gridExport > 0) {
    renewableBalance = 'grid_export';
  } else if (selfUsed > 0 || (consumed || 0) > 0) {
    renewableBalance = 'self_use';
  }

  return {
    powerConsumptionKwhPerMonth: consumed === null ? 0 : consumed,
    consumptionProvided,
    solarGenerationKwhPerMonth: generated,
    solarUsageKwhPerMonth: selfUsed,
    declaredSolarUsageKwhPerMonth: declaredUsage,
    netGridKwhPerMonth: gridImport,
    gridExportKwhPerMonth: gridExport,
    renewableBalance
  };
};

const normalizeIsoDate = (value) => {
  const text = String(value || '').trim();
  return /^\d{4}-\d{2}-\d{2}$/.test(text) ? text : '';
};

/**
 * @param {unknown} [value]
 */
export const normalizeRenewablePpa = (value = {}) => {
  const source = value && typeof value === 'object' && value.renewablePpa && typeof value.renewablePpa === 'object'
    ? value.renewablePpa
    : (value && typeof value === 'object' ? value : {});
  return {
    counterparty: String(source.counterparty || '').trim().slice(0, 200),
    reference: String(source.reference || '').trim().slice(0, 120),
    rateInrPerKwh: toNonNegativeNumber(source.rateInrPerKwh, 0),
    contractedKwhPerMonth: toNonNegativeNumber(source.contractedKwhPerMonth, 0),
    sourceDistanceKm: toNonNegativeNumber(source.sourceDistanceKm, 0),
    startDate: normalizeIsoDate(source.startDate),
    endDate: normalizeIsoDate(source.endDate)
  };
};

/**
 * Production cost uses the PPA rate only.
 * When the contract states a monthly quantity, the billed kilowatt-hours are
 * the lesser of generation and that quantity.
 */
export const renewableProductionCost = (generatedKwh, ppa = {}) => {
  const normalized = normalizeRenewablePpa(ppa);
  const generated = toNonNegativeNumber(generatedKwh, 0);
  const billedKwh = normalized.contractedKwhPerMonth > 0
    ? Math.min(generated, normalized.contractedKwhPerMonth)
    : generated;
  return {
    ...normalized,
    billedKwh,
    productionCostInr: roundTo(billedKwh * normalized.rateInrPerKwh)
  };
};

export const calculateSiteElectricityCarbon = (
  data = {},
  gridFactor = 0,
  renewableFactor = RENEWABLE_ELECTRICITY_KG_PER_KWH
) => {
  const allocation = allocateSiteRenewablePower(data);
  const grid = toNonNegativeNumber(gridFactor, 0);
  const renewable = toNonNegativeNumber(renewableFactor, RENEWABLE_ELECTRICITY_KG_PER_KWH);
  const location = normalizeRenewableGenerationLocation(data.renewableGenerationLocation);
  const sourceDistanceKm = normalizeRenewablePpa(data).sourceDistanceKm;
  const awayFromSite = location === 'near_site' || sourceDistanceKm > 0;
  const renewableTdLossRate = awayFromSite ? ELECTRICITY_TD_LOSS_RATE : 0;
  const facilityNetGridKgCo2 = roundTo(allocation.netGridKwhPerMonth * grid);
  const facilityRenewableUseKgCo2 = roundTo(allocation.solarUsageKwhPerMonth * renewable);
  const renewableTdLossKgCo2 = roundTo(facilityRenewableUseKgCo2 * renewableTdLossRate);
  const facilityElectricityKgCo2 = roundTo(
    facilityNetGridKgCo2 + facilityRenewableUseKgCo2 + renewableTdLossKgCo2
  );
  const gridExportDisplacementKgCo2 = roundTo(allocation.gridExportKwhPerMonth * grid);
  const solarAvoidedKgCo2 = roundTo(
    (allocation.solarUsageKwhPerMonth * grid) - facilityRenewableUseKgCo2 - renewableTdLossKgCo2
  );
  const production = renewableProductionCost(allocation.solarGenerationKwhPerMonth, data);

  return {
    ...allocation,
    renewableGenerationLocation: location,
    renewableSourceDistanceKm: sourceDistanceKm,
    gridEmissionFactorKgCo2PerKwh: grid,
    renewableEmissionFactorKgCo2PerKwh: renewable,
    renewableTdLossRate,
    renewableTdLossKgCo2,
    facilityNetGridKgCo2,
    facilityRenewableUseKgCo2,
    facilityElectricityKgCo2,
    gridExportDisplacementKgCo2,
    solarAvoidedKgCo2,
    gridExportCountedInTotal: false,
    renewablePpaRateInrPerKwh: production.rateInrPerKwh,
    renewablePpaBilledKwh: production.billedKwh,
    renewableProductionCostInr: production.productionCostInr
  };
};

export const RENEWABLE_GENERATION_LOCATIONS = Object.freeze({
  on_site: 'On the site',
  near_site: 'A short distance from the site'
});

/**
 * @param {unknown} [value]
 * @returns {'on_site' | 'near_site'}
 */
export const normalizeRenewableGenerationLocation = (value) => {
  const key = String(value || '').trim();
  return Object.prototype.hasOwnProperty.call(RENEWABLE_GENERATION_LOCATIONS, key) ? key : 'on_site';
};

export const describeSiteElectricity = (carbon = {}) => {
  const selfUsed = toNonNegativeNumber(carbon.solarUsageKwhPerMonth, 0);
  const generated = toNonNegativeNumber(carbon.solarGenerationKwhPerMonth, 0);
  const gridImport = toNonNegativeNumber(carbon.netGridKwhPerMonth, 0);
  const gridExport = toNonNegativeNumber(carbon.gridExportKwhPerMonth, 0);
  const renewableKg = toNonNegativeNumber(carbon.facilityRenewableUseKgCo2, 0);
  const gridKg = toNonNegativeNumber(carbon.facilityNetGridKgCo2, 0);
  const exportKg = toNonNegativeNumber(carbon.gridExportDisplacementKgCo2, 0);
  const renewableFactor = toNonNegativeNumber(carbon.renewableEmissionFactorKgCo2PerKwh, 0);
  const gridFactor = toNonNegativeNumber(carbon.gridEmissionFactorKgCo2PerKwh, 0);
  const tdKg = toNonNegativeNumber(carbon.renewableTdLossKgCo2, 0);
  const tdRate = toNonNegativeNumber(carbon.renewableTdLossRate, 0);
  const productionCost = toNonNegativeNumber(carbon.renewableProductionCostInr, 0);
  const ppaRate = toNonNegativeNumber(carbon.renewablePpaRateInrPerKwh, 0);
  const billedKwh = toNonNegativeNumber(carbon.renewablePpaBilledKwh, 0);

  let sentence;
  if (gridExport > 0) {
    sentence = `Renewable generation (${generated} kWh) is higher than power used. ${selfUsed} kWh is used on site at ${renewableFactor} kg CO2e/kWh (${renewableKg} kg CO2e). ${gridExport} kWh is exported to the grid. That export is ${exportKg} kg CO2e of grid displacement and stays outside the company total.`;
  } else if (selfUsed > 0 && gridImport > 0) {
    sentence = `Power used is higher than renewable generation. ${selfUsed} kWh of generation is used on site at ${renewableFactor} kg CO2e/kWh (${renewableKg} kg CO2e). Grid import is ${gridImport} kWh at ${gridFactor} kg CO2e/kWh (${gridKg} kg CO2e).`;
  } else if (selfUsed > 0) {
    sentence = `Renewable generation covers power used. ${selfUsed} kWh is used on site at ${renewableFactor} kg CO2e/kWh (${renewableKg} kg CO2e). None is exported to the grid.`;
  } else {
    sentence = `Grid import is ${gridImport} kWh at ${gridFactor} kg CO2e/kWh (${gridKg} kg CO2e).`;
  }
  if (tdKg > 0) {
    sentence += ` Transmission and distribution loss on renewable power brought to the site is ${tdKg} kg CO2e (${tdRate} times the renewable kilograms).`;
  }
  if (productionCost > 0) {
    sentence += ` Production cost follows the PPA rate of ${ppaRate} INR/kWh on ${billedKwh} kWh (${productionCost} INR).`;
  }
  const distanceKm = toNonNegativeNumber(carbon.renewableSourceDistanceKm, 0);
  if (distanceKm > 0) {
    sentence += ` The renewable source is ${distanceKm} km from the site.`;
  }
  return sentence;
};
