import React from 'react';
import {
  FormControl,
  FormControlLabel,
  FormHelperText,
  FormLabel,
  Radio,
  RadioGroup,
} from '@mui/material';
import {
  ELECTRICITY_TD_LOSS_RATE,
  RENEWABLE_GENERATION_LOCATIONS,
  normalizeRenewableGenerationLocation,
} from '../../shared/renewablePowerBalance';

export type RenewableGenerationLocation = keyof typeof RENEWABLE_GENERATION_LOCATIONS;

type RenewableGenerationLocationFieldProps = {
  value: string;
  onChange: (location: RenewableGenerationLocation) => void;
  sourceDistanceKm?: number;
  disabled?: boolean;
};

const RenewableGenerationLocationField: React.FC<RenewableGenerationLocationFieldProps> = ({
  value,
  onChange,
  sourceDistanceKm = 0,
  disabled = false,
}) => {
  const location = normalizeRenewableGenerationLocation(value);
  const distanceKm = Number(sourceDistanceKm) > 0 ? Number(sourceDistanceKm) : 0;
  const lossPercent = (ELECTRICITY_TD_LOSS_RATE * 100).toFixed(2);
  const awayFromSite = location === 'near_site' || distanceKm > 0;
  return (
    <FormControl component="fieldset" disabled={disabled} sx={{ mb: 1.5 }} data-testid="renewable-generation-location">
      <FormLabel component="legend">Where is the renewable plant?</FormLabel>
      <RadioGroup
        row
        name="renewableGenerationLocation"
        value={location}
        onChange={(event) => onChange(normalizeRenewableGenerationLocation(event.target.value))}
      >
        {Object.entries(RENEWABLE_GENERATION_LOCATIONS).map(([option, label]) => (
          <FormControlLabel
            key={option}
            value={option}
            control={<Radio />}
            label={label}
          />
        ))}
      </RadioGroup>
      <FormHelperText>
        {awayFromSite
          ? `Power brought to the site includes transmission and distribution loss at ${lossPercent}% of the renewable kilograms${distanceKm > 0 ? `. The PPA source is ${distanceKm} km from the site` : ''}.`
          : 'A plant on the site has no transmission and distribution loss. Enter the PPA distance when the source is away from the site.'}
      </FormHelperText>
    </FormControl>
  );
};

export default RenewableGenerationLocationField;
