import React from 'react';
import { Box, Button, Card, CardContent, LinearProgress, Stack, Typography } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import type { CompletenessResult } from '../../utils/sustainabilityUx';

export interface ProfileCompletenessCardProps {
  result: CompletenessResult;
  title?: string;
  actionPath: string;
  actionLabel?: string;
}

export const ProfileCompletenessCard: React.FC<ProfileCompletenessCardProps> = ({
  result,
  title = 'Profile completeness',
  actionPath,
  actionLabel = 'Improve profile',
}) => {
  const navigate = useNavigate();

  return (
    <Card variant="outlined" sx={{ mb: 2 }}>
      <CardContent>
        <Stack direction="row" justifyContent="space-between" alignItems="flex-start" sx={{ mb: 1 }}>
          <Box>
            <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
              {title}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {result.label}
            </Typography>
          </Box>
          <Typography variant="h6" sx={{ fontWeight: 800, color: 'primary.main' }}>
            {result.score}%
          </Typography>
        </Stack>
        <LinearProgress
          variant="determinate"
          value={result.score}
          sx={{ height: 8, borderRadius: 1, mb: 1.5 }}
        />
        {result.hints.length > 0 && (
          <Box component="ul" sx={{ m: 0, pl: 2.5, mb: 1.5 }}>
            {result.hints.map((hint) => (
              <Typography key={hint} component="li" variant="body2" color="text.secondary">
                {hint}
              </Typography>
            ))}
          </Box>
        )}
        {result.score < 100 && (
          <Button size="small" variant="outlined" onClick={() => navigate(actionPath)}>
            {actionLabel}
          </Button>
        )}
      </CardContent>
    </Card>
  );
};
